    @Test public void composedPortPreservesTheExistingPreparedTurnSnapshot()throws Exception {try(Harness h=new Harness(true)){CapabilityPort existing=new CapabilityPort(){public JSONArray tools()throws Exception{return new JSONArray().put(obj("type","function","function",obj("name","stale_catalog_tool")));}public boolean supports(String name){return name.equals("fresh_turn_tool");}public boolean sideEffecting(String name){return false;}public JSONObject execute(String name,JSONObject args,RunControl c){return new JSONObject();}public JSONObject prepareTurn(String q,int r,int s,RunControl c)throws Exception{return obj("tools",new JSONArray().put(obj("type","function","function",obj("name","fresh_turn_tool"))),"reference",obj("preparedSnapshot","retained"),"nativeTurnMarker",7);}};BrowserTaskCapabilityPort composed=new BrowserTaskCapabilityPort(h.space,h.authority,()->{},(b,c,id,n,args,pin)->obj("approved",true,"approvalId",UUID.randomUUID().toString()),h.ui,existing);JSONObject turn=composed.prepareTurn("research",1,1,h.control);assertEquals("retained",turn.getJSONObject("reference").getString("preparedSnapshot"));assertEquals(7,turn.getInt("nativeTurnMarker"));JSONArray tools=turn.getJSONArray("tools");assertEquals("fresh_turn_tool",tools.getJSONObject(0).getJSONObject("function").getString("name"));assertFalse(tools.toString().contains("stale_catalog_tool"));assertTrue(tools.toString().contains("browser_task_open"));}}
