        String tab=h.open("login");JSONObject before=h.observe(tab);h.invoke("request_user",obj("tabId",tab,"reason","在原页登录"));JSONObject pin=h.ui.call(()->{h.driver.pages.get(tab).put("url","https://example.com/workspace?document=original#actual").put("navigation",2L);return h.space.returnPinNative(tab);});String nonce=h.port.expectOwnerReturnObservation(pin,()->h.authority.check("browser_task_observe",h.control));h.ui.call(()->{h.space.returnOwnerNative(pin,()->{});h.control.resumeAtPauseRevision(pin.getLong("pauseRevision"));return null;});int reads=h.driver.observationReads.get();assertFalse(h.port.contextSnapshot("ordinary reference query").has("browserReturnObservation"));assertEquals(reads,h.driver.observationReads.get());
